import asyncio
import base64
import json
import os
import time
from typing import Any, Dict, List, Literal, Optional, Tuple

import httpx
from fastapi import FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel, Field

app = FastAPI()

_origins_raw = os.environ.get("CORS_ALLOW_ORIGINS", "*")
_origins = [o.strip() for o in _origins_raw.split(",") if o.strip()]
_allow_all = "*" in _origins
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"] if _allow_all else _origins,
    allow_credentials=False if _allow_all else True,
    allow_methods=["*"],
    allow_headers=["*"],
)

HTTP_TIMEOUT_S = float(os.environ.get("HTTP_TIMEOUT_S", "600"))
HTTP_CONNECT_TIMEOUT_S = float(os.environ.get("HTTP_CONNECT_TIMEOUT_S", "30"))
HTTP_READ_TIMEOUT_S = float(os.environ.get("HTTP_READ_TIMEOUT_S", "600"))
HTTP_WRITE_TIMEOUT_S = float(os.environ.get("HTTP_WRITE_TIMEOUT_S", "600"))
HTTP_POOL_TIMEOUT_S = float(os.environ.get("HTTP_POOL_TIMEOUT_S", "30"))

XAI_BASE_URL = os.environ.get("XAI_BASE_URL", "").rstrip("/")
EXA_BASE_URL = os.environ.get("EXA_BASE_URL", "").rstrip("/")
PARALLEL_BASE_URL = os.environ.get("PARALLEL_BASE_URL", "").rstrip("/")

DEFAULT_XAI_MODEL = os.environ.get("XAI_DEFAULT_MODEL", "grok-4")
DEFAULT_GEMINI_MODEL = os.environ.get("GEMINI_DEFAULT_MODEL", "gemini-3-pro-preview")
DEFAULT_GEMINI_IMAGE_MODEL = os.environ.get("GEMINI_IMAGE_MODEL", "gemini-3-pro-image-preview")
DEFAULT_BEDROCK_MODEL_ID = os.environ.get("BEDROCK_MODEL_ID", "")
DEFAULT_PARALLEL_PROCESSOR = os.environ.get("PARALLEL_PROCESSOR", "ultra8x")

XAI_MAX_OUTPUT_TOKENS = int(os.environ.get("XAI_MAX_OUTPUT_TOKENS", "32768"))
GEMINI_MAX_OUTPUT_TOKENS = int(os.environ.get("GEMINI_MAX_OUTPUT_TOKENS", "65536"))
GEMINI_IMAGE_MAX_OUTPUT_TOKENS = int(os.environ.get("GEMINI_IMAGE_MAX_OUTPUT_TOKENS", "32768"))
BEDROCK_MAX_OUTPUT_TOKENS = int(os.environ.get("BEDROCK_MAX_OUTPUT_TOKENS", "8192"))

PARALLEL_RESULT_BLOCKING_TIMEOUT_S = float(os.environ.get("PARALLEL_RESULT_BLOCKING_TIMEOUT_S", "1800"))
PARALLEL_POLL_INTERVAL_S = float(os.environ.get("PARALLEL_POLL_INTERVAL_S", "2.0"))

MAX_PROMPT_CHARS = int(os.environ.get("MAX_PROMPT_CHARS", "2000000"))
MAX_SYSTEM_CHARS = int(os.environ.get("MAX_SYSTEM_CHARS", "200000"))

MAX_EXA_RESULTS = int(os.environ.get("MAX_EXA_RESULTS", "50"))


class GenerateRequest(BaseModel):
    provider: Literal["xai", "gemini", "gemini_image", "bedrock_claude", "exa", "parallel"]
    prompt: str = Field(min_length=1)
    system: Optional[str] = None
    model: Optional[str] = None
    options: Dict[str, Any] = Field(default_factory=dict)


def _require_env(name: str) -> str:
    value = os.environ.get(name)
    if not value:
        raise HTTPException(status_code=500, detail=f"Missing required environment variable: {name}")
    return value


def _clip(s: Optional[str], max_len: int) -> Optional[str]:
    if s is None:
        return None
    if len(s) <= max_len:
        return s
    return s[:max_len]


def _timeout() -> httpx.Timeout:
    return httpx.Timeout(
        timeout=HTTP_TIMEOUT_S,
        connect=HTTP_CONNECT_TIMEOUT_S,
        read=HTTP_READ_TIMEOUT_S,
        write=HTTP_WRITE_TIMEOUT_S,
        pool=HTTP_POOL_TIMEOUT_S,
    )


async def _post_json(url: str, headers: Dict[str, str], payload: Dict[str, Any]) -> Dict[str, Any]:
    async with httpx.AsyncClient(timeout=_timeout()) as client:
        r = await client.post(url, headers=headers, json=payload)
        ct = r.headers.get("content-type", "")
        if r.status_code >= 400:
            body: Any = None
            try:
                body = r.json() if "application/json" in ct else r.text[:4000]
            except Exception:
                body = r.text[:4000]
            raise HTTPException(status_code=502, detail={"upstream_status": r.status_code, "url": url, "body": body})
        if "application/json" in ct:
            return r.json()
        try:
            return json.loads(r.text)
        except Exception:
            return {"raw": r.text}


async def _get_json(url: str, headers: Dict[str, str]) -> Dict[str, Any]:
    async with httpx.AsyncClient(timeout=_timeout()) as client:
        r = await client.get(url, headers=headers)
        ct = r.headers.get("content-type", "")
        if r.status_code >= 400:
            body: Any = None
            try:
                body = r.json() if "application/json" in ct else r.text[:4000]
            except Exception:
                body = r.text[:4000]
            raise HTTPException(status_code=502, detail={"upstream_status": r.status_code, "url": url, "body": body})
        if "application/json" in ct:
            return r.json()
        try:
            return json.loads(r.text)
        except Exception:
            return {"raw": r.text}


def _bool(v: Any, default: bool = False) -> bool:
    if v is None:
        return default
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return bool(v)
    if isinstance(v, str):
        s = v.strip().lower()
        if s in ("1", "true", "yes", "y", "on"):
            return True
        if s in ("0", "false", "no", "n", "off"):
            return False
    return default


async def call_xai_chat(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    api_key = _require_env("XAI_API_KEY")
    url = f"{XAI_BASE_URL}/chat/completions"
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    temperature = float(options.get("temperature", 0.2))
    top_p = float(options.get("top_p", 1.0))
    max_tokens = int(options.get("max_tokens", XAI_MAX_OUTPUT_TOKENS))
    max_tokens = max(max_tokens, XAI_MAX_OUTPUT_TOKENS)

    messages: List[Dict[str, Any]] = []
    if system:
        messages.append({"role": "system", "content": system})
    messages.append({"role": "user", "content": prompt})

    payload: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
        "top_p": top_p,
        "stream": False,
    }

    data = await _post_json(url, headers, payload)
    text: Optional[str] = None
    try:
        text = data["choices"][0]["message"]["content"]
    except Exception:
        text = None
    return {"text": text, "raw": data}


def _run_gemini_text_sync(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    try:
        from google import genai
        from google.genai import types
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"google-genai not available: {type(e).__name__}: {e}")

    api_key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise HTTPException(status_code=500, detail="Missing required environment variable: GEMINI_API_KEY (or GOOGLE_API_KEY)")

    client = genai.Client(api_key=api_key)

    temperature = float(options.get("temperature", 0.2))
    top_p = float(options.get("top_p", 0.95))
    top_k = int(options.get("top_k", 40))
    max_output_tokens = int(options.get("max_tokens", GEMINI_MAX_OUTPUT_TOKENS))
    max_output_tokens = max(max_output_tokens, GEMINI_MAX_OUTPUT_TOKENS)

    parts = []
    if system:
        parts.append(types.Part.from_text(text=system))
    parts.append(types.Part.from_text(text=prompt))

    cfg = types.GenerateContentConfig(
        temperature=temperature,
        top_p=top_p,
        top_k=top_k,
        max_output_tokens=max_output_tokens,
    )

    resp = client.models.generate_content(model=model, contents=parts, config=cfg)
    text = getattr(resp, "text", None)

    raw: Any = None
    try:
        raw = resp.model_dump() if hasattr(resp, "model_dump") else {"text": text}
    except Exception:
        raw = {"text": text}

    return {"text": text, "raw": raw}


def _gemini_extract_stream_parts(chunk: Any) -> Tuple[List[Tuple[str, bytes]], List[str]]:
    images: List[Tuple[str, bytes]] = []
    texts: List[str] = []

    candidates = getattr(chunk, "candidates", None)
    if not candidates or not isinstance(candidates, list) or len(candidates) == 0:
        t = getattr(chunk, "text", None)
        if isinstance(t, str) and t:
            texts.append(t)
        return images, texts

    c0 = candidates[0]
    content = getattr(c0, "content", None)
    if content is None:
        t = getattr(chunk, "text", None)
        if isinstance(t, str) and t:
            texts.append(t)
        return images, texts

    parts = getattr(content, "parts", None)
    if not parts or not isinstance(parts, list):
        t = getattr(chunk, "text", None)
        if isinstance(t, str) and t:
            texts.append(t)
        return images, texts

    for p in parts:
        inline = getattr(p, "inline_data", None)
        if inline is not None:
            data = getattr(inline, "data", None)
            mime = getattr(inline, "mime_type", None) or getattr(inline, "mimeType", None)
            if isinstance(data, (bytes, bytearray)) and isinstance(mime, str) and mime:
                images.append((mime, bytes(data)))
                continue
        t = getattr(p, "text", None)
        if isinstance(t, str) and t:
            texts.append(t)

    return images, texts


def _run_gemini_image_sync(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    try:
        from google import genai
        from google.genai import types
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"google-genai not available: {type(e).__name__}: {e}")

    api_key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise HTTPException(status_code=500, detail="Missing required environment variable: GEMINI_API_KEY (or GOOGLE_API_KEY)")

    client = genai.Client(api_key=api_key)

    temperature = float(options.get("temperature", 0.05))
    max_output_tokens = int(options.get("max_tokens", GEMINI_IMAGE_MAX_OUTPUT_TOKENS))
    max_output_tokens = max(max_output_tokens, GEMINI_IMAGE_MAX_OUTPUT_TOKENS)

    user_text = prompt if system is None else (system + "\n" + prompt)

    contents = [
        types.Content(
            role="user",
            parts=[types.Part.from_text(text=user_text)],
        ),
    ]

    tools = []
    if _bool(options.get("google_search", True), True):
        tools = [types.Tool(googleSearch=types.GoogleSearch())]

    image_size = str(options.get("image_size", "4K"))

    cfg = types.GenerateContentConfig(
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        response_modalities=["IMAGE", "TEXT"],
        image_config=types.ImageConfig(image_size=image_size),
        tools=tools,
    )

    images_out: List[Dict[str, Any]] = []
    text_out_parts: List[str] = []

    stream = client.models.generate_content_stream(model=model, contents=contents, config=cfg)
    for chunk in stream:
        imgs, texts = _gemini_extract_stream_parts(chunk)
        for mime, b in imgs:
            images_out.append(
                {
                    "mime_type": mime,
                    "base64": base64.b64encode(b).decode("ascii"),
                }
            )
        for t in texts:
            text_out_parts.append(t)

    out_text = "".join(text_out_parts).strip() if text_out_parts else None
    raw = {"text": out_text, "images": images_out}

    return {"text": out_text, "raw": raw}


async def call_gemini_text(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_gemini_text_sync, prompt, system, model, options)


async def call_gemini_image(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_gemini_image_sync, prompt, system, model, options)


def _run_bedrock_sync(prompt: str, system: Optional[str], model_id: str, options: Dict[str, Any]) -> Dict[str, Any]:
    try:
        import boto3
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"boto3 not available: {type(e).__name__}: {e}")

    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    if not region:
        raise HTTPException(status_code=500, detail="Missing AWS region: set AWS_REGION (or AWS_DEFAULT_REGION)")
    if not model_id:
        raise HTTPException(status_code=500, detail="Missing required environment variable: BEDROCK_MODEL_ID")

    max_tokens = int(options.get("max_tokens", BEDROCK_MAX_OUTPUT_TOKENS))
    max_tokens = max(max_tokens, BEDROCK_MAX_OUTPUT_TOKENS)
    temperature = float(options.get("temperature", 0.2))
    top_p = float(options.get("top_p", 1.0))

    brt = boto3.client("bedrock-runtime", region_name=region)

    body: Dict[str, Any] = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens,
        "temperature": temperature,
        "top_p": top_p,
        "messages": [{"role": "user", "content": [{"type": "text", "text": prompt}]}],
    }
    if system:
        body["system"] = system

    resp = brt.invoke_model(modelId=model_id, body=json.dumps(body).encode("utf-8"))
    payload = resp.get("body")
    raw_bytes = payload.read() if hasattr(payload, "read") else payload
    raw_text = raw_bytes.decode("utf-8") if isinstance(raw_bytes, (bytes, bytearray)) else str(raw_bytes)

    try:
        raw_json = json.loads(raw_text)
    except Exception:
        raw_json = {"raw": raw_text}

    text: Optional[str] = None
    try:
        content = raw_json.get("content", [])
        if isinstance(content, list):
            parts: List[str] = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text":
                    t = item.get("text")
                    if isinstance(t, str):
                        parts.append(t)
            text = "".join(parts) if parts else None
    except Exception:
        text = None

    return {"text": text, "raw": raw_json}


async def call_bedrock_claude(prompt: str, system: Optional[str], model_id: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_bedrock_sync, prompt, system, model_id, options)


async def call_exa_search(prompt: str, options: Dict[str, Any]) -> Dict[str, Any]:
    api_key = _require_env("EXA_API_KEY")
    url = f"{EXA_BASE_URL}/search"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-api-key": api_key,
    }

    num_results = int(options.get("num_results", MAX_EXA_RESULTS))
    num_results = max(num_results, MAX_EXA_RESULTS)
    num_results = min(num_results, 200)

    payload: Dict[str, Any] = {
        "query": prompt,
        "numResults": num_results,
        "useAutoprompt": _bool(options.get("use_autoprompt", True), True),
    }
    if "include_domains" in options and isinstance(options["include_domains"], list):
        payload["includeDomains"] = options["include_domains"]
    if "exclude_domains" in options and isinstance(options["exclude_domains"], list):
        payload["excludeDomains"] = options["exclude_domains"]
    if "start_published_date" in options and isinstance(options["start_published_date"], str):
        payload["startPublishedDate"] = options["start_published_date"]
    if "end_published_date" in options and isinstance(options["end_published_date"], str):
        payload["endPublishedDate"] = options["end_published_date"]

    data = await _post_json(url, headers, payload)
    return {"text": None, "raw": data}


async def call_parallel_deepsearch(prompt: str, options: Dict[str, Any]) -> Dict[str, Any]:
    api_key = _require_env("PARALLEL_API_KEY")
    processor = str(options.get("processor", DEFAULT_PARALLEL_PROCESSOR))
    create_url = f"{PARALLEL_BASE_URL}/v1/tasks/runs"
    headers = {"Content-Type": "application/json", "x-api-key": api_key}
    create_payload: Dict[str, Any] = {"input": prompt, "processor": processor}

    if "task_spec" in options and isinstance(options["task_spec"], dict):
        create_payload["task_spec"] = options["task_spec"]

    run = await _post_json(create_url, headers, create_payload)
    run_id = run.get("run_id") or run.get("id") or run.get("task_run", {}).get("run_id")
    if not run_id or not isinstance(run_id, str):
        raise HTTPException(status_code=502, detail={"error": "Parallel did not return run_id", "raw": run})

    result_url = f"{PARALLEL_BASE_URL}/v1/tasks/runs/{run_id}/result"
    deadline = time.time() + PARALLEL_RESULT_BLOCKING_TIMEOUT_S

    last_error: Optional[Dict[str, Any]] = None
    while True:
        if time.time() >= deadline:
            raise HTTPException(status_code=504, detail={"error": "Parallel result timeout", "run_id": run_id, "last_error": last_error})
        try:
            result = await _get_json(result_url, headers)
            return {"text": None, "raw": {"run": run, "result": result}}
        except HTTPException as e:
            last_error = {"detail": e.detail}
            await asyncio.sleep(PARALLEL_POLL_INTERVAL_S)


@app.get("/")
async def root() -> FileResponse:
    return FileResponse("index.html")


@app.get("/health")
async def health() -> Dict[str, str]:
    return {"status": "ok", "limits_spec": "[web:75]"}


@app.post("/api/generate")
async def generate(req: GenerateRequest, request: Request) -> JSONResponse:
    prompt = _clip(req.prompt, MAX_PROMPT_CHARS)
    system = _clip(req.system, MAX_SYSTEM_CHARS)
    if not prompt:
        raise HTTPException(status_code=400, detail="Empty prompt after clipping")

    provider = req.provider

    if provider == "xai":
        model = req.model or DEFAULT_XAI_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), XAI_MAX_OUTPUT_TOKENS)
        result = await call_xai_chat(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "gemini":
        model = req.model or DEFAULT_GEMINI_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), GEMINI_MAX_OUTPUT_TOKENS)
        result = await call_gemini_text(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "gemini_image":
        model = req.model or DEFAULT_GEMINI_IMAGE_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), GEMINI_IMAGE_MAX_OUTPUT_TOKENS)
        if "temperature" not in options:
            options["temperature"] = 0.05
        if "image_size" not in options:
            options["image_size"] = "4K"
        if "google_search" not in options:
            options["google_search"] = True
        result = await call_gemini_image(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "bedrock_claude":
        model_id = req.model or DEFAULT_BEDROCK_MODEL_ID
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), BEDROCK_MAX_OUTPUT_TOKENS)
        result = await call_bedrock_claude(prompt, system, model_id, options)
        return JSONResponse({"provider": provider, "model": model_id, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "exa":
        options = dict(req.options or {})
        options["num_results"] = max(int(options.get("num_results", 0)), MAX_EXA_RESULTS)
        result = await call_exa_search(prompt, options)
        return JSONResponse({"provider": provider, "model": None, "output": None, "raw": result.get("raw")})

    if provider == "parallel":
        options = dict(req.options or {})
        if "processor" not in options:
            options["processor"] = DEFAULT_PARALLEL_PROCESSOR
        result = await call_parallel_deepsearch(prompt, options)
        return JSONResponse({"provider": provider, "model": options.get("processor"), "output": None, "raw": result.get("raw")})

    raise HTTPException(status_code=400, detail="Unsupported provider")
