def _clip(s: Optional[str], max_len: int) -> Optional[str]:
    if s is None:
        return None
    if len(s) <= max_len:
        return s
    return s[:max_len]


def _timeout() -> httpx.Timeout:
    return httpx.Timeout(
        timeout=HTTP_TIMEOUT_S,
        connect=HTTP_CONNECT_TIMEOUT_S,
