    api_key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise HTTPException(status_code=500, detail="Missing required environment variable: GEMINI_API_KEY (or GOOGLE_API_KEY)")

    client = genai.Client(api_key=api_key)

    temperature = float(options.get("temperature", 0.2))
    top_p = float(options.get("top_p", 0.95))
    top_k = int(options.get("top_k", 40))
    max_output_tokens = int(options.get("max_tokens", GEMINI_MAX_OUTPUT_TOKENS))
    max_output_tokens = max(max_output_tokens, GEMINI_MAX_OUTPUT_TOKENS)

    parts = []
    if system:
        parts.append(types.Part.from_text(text=system))
    parts.append(types.Part.from_text(text=prompt))

    cfg = types.GenerateContentConfig(
        temperature=temperature,
        top_p=top_p,
        top_k=top_k,
        max_output_tokens=max_output_tokens,
