    max_output_tokens = max(max_output_tokens, GEMINI_IMAGE_MAX_OUTPUT_TOKENS)

    user_text = prompt if system is None else (system + "\n" + prompt)

    contents = [
        types.Content(
            role="user",
            parts=[types.Part.from_text(text=user_text)],
        ),
    ]

    tools = []
    if _bool(options.get("google_search", True), True):
        tools = [types.Tool(googleSearch=types.GoogleSearch())]

    image_size = str(options.get("image_size", "4K"))

    cfg = types.GenerateContentConfig(
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        response_modalities=["IMAGE", "TEXT"],
        image_config=types.ImageConfig(image_size=image_size),
        tools=tools,
