            )
        for t in texts:
            text_out_parts.append(t)

    out_text = "".join(text_out_parts).strip() if text_out_parts else None
    raw = {"text": out_text, "images": images_out}

    return {"text": out_text, "raw": raw}


async def call_gemini_text(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_gemini_text_sync, prompt, system, model, options)


async def call_gemini_image(prompt: str, system: Optional[str], model: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_gemini_image_sync, prompt, system, model, options)


def _run_bedrock_sync(prompt: str, system: Optional[str], model_id: str, options: Dict[str, Any]) -> Dict[str, Any]:
    try:
