    except Exception as e:
        raise HTTPException(status_code=500, detail=f"boto3 not available: {type(e).__name__}: {e}")

    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    if not region:
        raise HTTPException(status_code=500, detail="Missing AWS region: set AWS_REGION (or AWS_DEFAULT_REGION)")
    if not model_id:
        raise HTTPException(status_code=500, detail="Missing required environment variable: BEDROCK_MODEL_ID")

    max_tokens = int(options.get("max_tokens", BEDROCK_MAX_OUTPUT_TOKENS))
    max_tokens = max(max_tokens, BEDROCK_MAX_OUTPUT_TOKENS)
    temperature = float(options.get("temperature", 0.2))
    top_p = float(options.get("top_p", 1.0))

    brt = boto3.client("bedrock-runtime", region_name=region)

    body: Dict[str, Any] = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens,
        "temperature": temperature,
        "top_p": top_p,
        "messages": [{"role": "user", "content": [{"type": "text", "text": prompt}]}],
    }
    if system:
        body["system"] = system

    resp = brt.invoke_model(modelId=model_id, body=json.dumps(body).encode("utf-8"))
    payload = resp.get("body")
    raw_bytes = payload.read() if hasattr(payload, "read") else payload
    raw_text = raw_bytes.decode("utf-8") if isinstance(raw_bytes, (bytes, bytearray)) else str(raw_bytes)

    try:
        raw_json = json.loads(raw_text)
    except Exception:
        raw_json = {"raw": raw_text}

    text: Optional[str] = None
    try:
        content = raw_json.get("content", [])
        if isinstance(content, list):
            parts: List[str] = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text":
                    t = item.get("text")
                    if isinstance(t, str):
                        parts.append(t)
            text = "".join(parts) if parts else None
    except Exception:
        text = None

    return {"text": text, "raw": raw_json}


async def call_bedrock_claude(prompt: str, system: Optional[str], model_id: str, options: Dict[str, Any]) -> Dict[str, Any]:
    return await asyncio.to_thread(_run_bedrock_sync, prompt, system, model_id, options)


async def call_exa_search(prompt: str, options: Dict[str, Any]) -> Dict[str, Any]:
    api_key = _require_env("EXA_API_KEY")
    url = f"{EXA_BASE_URL}/search"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-api-key": api_key,
    }

    num_results = int(options.get("num_results", MAX_EXA_RESULTS))
    num_results = max(num_results, MAX_EXA_RESULTS)
    num_results = min(num_results, 200)

    payload: Dict[str, Any] = {
        "query": prompt,
        "numResults": num_results,
        "useAutoprompt": _bool(options.get("use_autoprompt", True), True),
    }
    if "include_domains" in options and isinstance(options["include_domains"], list):
        payload["includeDomains"] = options["include_domains"]
    if "exclude_domains" in options and isinstance(options["exclude_domains"], list):
        payload["excludeDomains"] = options["exclude_domains"]
    if "start_published_date" in options and isinstance(options["start_published_date"], str):
        payload["startPublishedDate"] = options["start_published_date"]
    if "end_published_date" in options and isinstance(options["end_published_date"], str):
        payload["endPublishedDate"] = options["end_published_date"]

    data = await _post_json(url, headers, payload)
    return {"text": None, "raw": data}


async def call_parallel_deepsearch(prompt: str, options: Dict[str, Any]) -> Dict[str, Any]:
    api_key = _require_env("PARALLEL_API_KEY")
    processor = str(options.get("processor", DEFAULT_PARALLEL_PROCESSOR))
    create_url = f"{PARALLEL_BASE_URL}/v1/tasks/runs"
    headers = {"Content-Type": "application/json", "x-api-key": api_key}
    create_payload: Dict[str, Any] = {"input": prompt, "processor": processor}

    if "task_spec" in options and isinstance(options["task_spec"], dict):
        create_payload["task_spec"] = options["task_spec"]

    run = await _post_json(create_url, headers, create_payload)
    run_id = run.get("run_id") or run.get("id") or run.get("task_run", {}).get("run_id")
    if not run_id or not isinstance(run_id, str):
        raise HTTPException(status_code=502, detail={"error": "Parallel did not return run_id", "raw": run})

    result_url = f"{PARALLEL_BASE_URL}/v1/tasks/runs/{run_id}/result"
    deadline = time.time() + PARALLEL_RESULT_BLOCKING_TIMEOUT_S

    last_error: Optional[Dict[str, Any]] = None
    while True:
        if time.time() >= deadline:
            raise HTTPException(status_code=504, detail={"error": "Parallel result timeout", "run_id": run_id, "last_error": last_error})
        try:
            result = await _get_json(result_url, headers)
            return {"text": None, "raw": {"run": run, "result": result}}
        except HTTPException as e:
            last_error = {"detail": e.detail}
            await asyncio.sleep(PARALLEL_POLL_INTERVAL_S)


@app.get("/")
async def root() -> FileResponse:
    return FileResponse("index.html")


@app.get("/health")
async def health() -> Dict[str, str]:
    return {"status": "ok", "limits_spec": "[web:75]"}


@app.post("/api/generate")
async def generate(req: GenerateRequest, request: Request) -> JSONResponse:
    prompt = _clip(req.prompt, MAX_PROMPT_CHARS)
    system = _clip(req.system, MAX_SYSTEM_CHARS)
    if not prompt:
        raise HTTPException(status_code=400, detail="Empty prompt after clipping")

    provider = req.provider

    if provider == "xai":
        model = req.model or DEFAULT_XAI_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), XAI_MAX_OUTPUT_TOKENS)
        result = await call_xai_chat(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "gemini":
        model = req.model or DEFAULT_GEMINI_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), GEMINI_MAX_OUTPUT_TOKENS)
        result = await call_gemini_text(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "gemini_image":
        model = req.model or DEFAULT_GEMINI_IMAGE_MODEL
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), GEMINI_IMAGE_MAX_OUTPUT_TOKENS)
        if "temperature" not in options:
            options["temperature"] = 0.05
        if "image_size" not in options:
            options["image_size"] = "4K"
        if "google_search" not in options:
            options["google_search"] = True
        result = await call_gemini_image(prompt, system, model, options)
        return JSONResponse({"provider": provider, "model": model, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "bedrock_claude":
        model_id = req.model or DEFAULT_BEDROCK_MODEL_ID
        options = dict(req.options or {})
        options["max_tokens"] = max(int(options.get("max_tokens", 0)), BEDROCK_MAX_OUTPUT_TOKENS)
        result = await call_bedrock_claude(prompt, system, model_id, options)
        return JSONResponse({"provider": provider, "model": model_id, "output": result.get("text"), "raw": result.get("raw")})

    if provider == "exa":
        options = dict(req.options or {})
        options["num_results"] = max(int(options.get("num_results", 0)), MAX_EXA_RESULTS)
        result = await call_exa_search(prompt, options)
        return JSONResponse({"provider": provider, "model": None, "output": None, "raw": result.get("raw")})

    if provider == "parallel":
        options = dict(req.options or {})
        if "processor" not in options:
            options["processor"] = DEFAULT_PARALLEL_PROCESSOR
        result = await call_parallel_deepsearch(prompt, options)
        return JSONResponse({"provider": provider, "model": options.get("processor"), "output": None, "raw": result.get("raw")})

    raise HTTPException(status_code=400, detail="Unsupported provider")
