    <div class="grid">
      <section class="card">
        <div class="row">
          <div>
            <label>Provider</label>
            <select id="provider">
              <option value="xai">xAI (Grok)</option>
              <option value="gemini">Google (Gemini 3)</option>
              <option value="gemini_image">Google (Gemini 3 Image)</option>
              <option value="bedrock_claude">AWS Bedrock (Claude)</option>
              <option value="parallel">Parallel (Deep Research)</option>
              <option value="exa">Exa (Web Search)</option>
            </select>
          </div>
          <div>
            <label>Model / Model ID (opcionális)</label>
            <input id="model" class="mono" placeholder="">
