        <div class="row" style="margin-top:12px;">
          <div>
            <label>Temperature</label>
            <input id="temperature" class="mono" type="number" step="0.01" min="0" max="2" value="0.2">
          </div>
          <div>
            <label>Max tokens (kényszerítve maximumra)</label>
            <input id="maxTokens" class="mono" type="number" step="1" min="0" value="0" disabled>
          </div>
        </div>

        <div style="margin-top:12px;">
          <label>System (opcionális)</label>
          <textarea id="system" class="mono" placeholder=""></textarea>
