        <div class="actions">
          <button class="secondary" id="clearBtn">Törlés</button>
          <button id="sendBtn">Küldés</button>
        </div>

        <div class="status">
          <div class="pill" id="healthPill">Health: ismeretlen</div>
          <div class="hint mono" id="latency"></div>
