  <script>
    const el = (id) => document.getElementById(id);

    const providerEl = el("provider");
    const modelEl = el("model");
    const systemEl = el("system");
    const promptEl = el("prompt");
    const temperatureEl = el("temperature");
    const maxTokensEl = el("maxTokens");
    const sendBtn = el("sendBtn");
    const clearBtn = el("clearBtn");
    const outputEl = el("output");
    const rawEl = el("raw");
    const healthPill = el("healthPill");
    const latencyEl = el("latency");
    const baseUrlEl = el("baseUrl");
    const imagesEl = el("images");

    baseUrlEl.textContent = location.origin;

    const maxTokensByProvider = {
      xai: 32768,
      gemini: 65536,
      gemini_image: 32768,
      bedrock_claude: 8192,
      parallel: 0,
      exa: 0
    };

    const defaultsByProvider = {
      xai: { model: "grok-4", temperature: 0.2, system: "", prompt: "Válaszolj a lehető legrészletesebben: írj egy teljes, biztonságos, production API kliens mintát hibakezeléssel és retry stratégiával." },
      gemini: { model: "gemini-3-pro-preview", temperature: 0.2, system: "", prompt: "Adj egy részletes, hosszú választ: hogyan tervezzünk nagy terhelésű FastAPI szolgáltatást idempotens endpointokkal?" },
      gemini_image: { model: "gemini-3-pro-image-preview", temperature: 0.05, system: "", prompt: "Készíts 4K képet: fotórealisztikus stúdiótermékfotó egy fekete, matt okosóráról, üveg reflektálódással, fehér háttéren, magas részletességgel." },
      bedrock_claude: { model: "", temperature: 0.2, system: "", prompt: "Írj egy teljes, részletes útmutatót: hogyan kell production loggingot és tracinget bevezetni FastAPI + async HTTP kliensekhez." },
      parallel: { model: "", temperature: 0.2, system: "", prompt: "Végezz deep research jellegű kutatást: a legjobb gyakorlatok HTTP timeoutok és retry policy beállítására, forrásokra bontva." },
      exa: { model: "", temperature: 0.2, system: "", prompt: "FastAPI production retry backoff idempotency best practices" }
    };

    function setMaxTokensUI() {
      const p = providerEl.value;
      maxTokensEl.value = String(maxTokensByProvider[p] || 0);
    }

    function setDefaults() {
      const p = providerEl.value;
      const d = defaultsByProvider[p] || { model:"", temperature:0.2, system:"", prompt:"" };
      if (!modelEl.value.trim()) modelEl.value = d.model;
      temperatureEl.value = String(d.temperature);
      if (!systemEl.value.trim()) systemEl.value = d.system;
      if (!promptEl.value.trim()) promptEl.value = d.prompt;
      setMaxTokensUI();
    }

    function jsonPretty(x) {
      try { return JSON.stringify(x, null, 2); } catch (e) { return String(x); }
    }

    function setBusy(b) {
      sendBtn.disabled = b;
      providerEl.disabled = b;
      modelEl.disabled = b;
      systemEl.disabled = b;
      promptEl.disabled = b;
      temperatureEl.disabled = b;
      clearBtn.disabled = b;
    }

    function clearImages() {
      while (imagesEl.firstChild) imagesEl.removeChild(imagesEl.firstChild);
    }

    function renderImages(raw) {
      clearImages();
      if (!raw || typeof raw !== "object") return;
      const images = raw.images || (raw.result && raw.result.images) || null;
      if (!images || !Array.isArray(images) || images.length === 0) return;
      for (const img of images) {
        if (!img || typeof img !== "object") continue;
        const mime = img.mime_type || img.mimeType || "image/png";
        const b64 = img.base64 || null;
        if (!b64 || typeof b64 !== "string") continue;
        const imageEl = document.createElement("img");
        imageEl.alt = "generated";
        imageEl.src = `data:${mime};base64,${b64}`;
        imagesEl.appendChild(imageEl);
      }
    }

    async function checkHealth() {
      try {
        const r = await fetch("/health", { method: "GET" });
        if (!r.ok) throw new Error("bad");
        const j = await r.json();
        healthPill.textContent = "Health: " + (j.status || "ok");
        healthPill.className = "pill ok";
      } catch (e) {
        healthPill.textContent = "Health: hiba";
        healthPill.className = "pill bad";
      }
    }

    async function send() {
      outputEl.textContent = "";
      rawEl.textContent = "";
      latencyEl.textContent = "";
      clearImages();
      setBusy(true);
      const t0 = performance.now();
      try {
        const provider = providerEl.value;
        const model = modelEl.value.trim() || null;
        const system = systemEl.value.trim() || null;
        const prompt = promptEl.value.trim();
        const temperature = Number(temperatureEl.value);

        const options = { temperature, max_tokens: Number(maxTokensEl.value) };

        if (provider === "parallel") options.processor = "ultra8x";
        if (provider === "gemini_image") {
          options.image_size = "4K";
          options.google_search = true;
          options.temperature = 0.05;
        }

        const payload = { provider, model, system, prompt, options };

        const r = await fetch("/api/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        });

        const j = await r.json();
        const t1 = performance.now();
        latencyEl.textContent = "Latency: " + Math.round(t1 - t0) + " ms";

        if (!r.ok) {
          outputEl.textContent = "Hiba";
          rawEl.textContent = jsonPretty(j);
          return;
        }

        renderImages(j.raw);
        outputEl.textContent = (j.output === null || typeof j.output === "undefined") ? "" : String(j.output);
        rawEl.textContent = jsonPretty(j.raw);
      } catch (e) {
        rawEl.textContent = String(e && e.message ? e.message : e);
      } finally {
        setBusy(false);
      }
    }

    providerEl.addEventListener("change", () => {
      modelEl.value = "";
      systemEl.value = "";
      promptEl.value = "";
      clearImages();
      setDefaults();
    });

    clearBtn.addEventListener("click", () => {
      modelEl.value = "";
      systemEl.value = "";
      promptEl.value = "";
      outputEl.textContent = "";
      rawEl.textContent = "";
      latencyEl.textContent = "";
      clearImages();
      setDefaults();
    });

    sendBtn.addEventListener("click", send);

    window.addEventListener("keydown", (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") send();
    });

    setDefaults();
    checkHealth();
    setInterval(checkHealth, 8000);
  </script>
